/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
// Exports the contents of a grid (using the selected order and filters) to a PDF file. &IsAuthorized = SecGAMIsAuthByFunctionalityKey.Udp(!'trnsremessasww_Execute') If &IsAuthorized
LoadWWPContext.Call(&WWPContext)
Do 'LoadGridState'
&Title = "Lista de Remessa de Alimentação"
//Report Template Source Header &AppName = "DVelop Software Solutions" &Phone = !"+1 550 8923" &Mail = !"info@mail.com" &Website = !"http://www.web.com" &AddressLine1 = !"French Boulevard 2859" &AddressLine2 = !"Downtown" &AddressLine3 = !"Paris, France" Print printTitle End Footer &PageInfo = "Page: " + &Page.ToString().Trim() &DateInfo = "Date: " + &Today.ToFormattedString() Print printFooter End
Do 'PrintFilters'
Do 'PrintColumnTitles'
Do 'PrintData'
Do 'PrintFooter'
EndIf
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
Sub 'PrintFilters'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
If &GridState.DynamicFilters.Count >= 1 &GridStateDynamicFilter = &GridState.DynamicFilters.Item(1) &DynamicFiltersSelector1 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector1 = !'REMCODIGO' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &remCodigo1.FromString(&GridStateDynamicFilter.Value) If not &remCodigo1.IsEmpty() Do Case Case &DynamicFiltersOperator1 = 0 &FilterremCodigoDescription = format('%1 (%2)', "Código", "=") EndCase &remCodigo = &remCodigo1 print printBlockFilterremCodigo EndIf Case &DynamicFiltersSelector1 = !'REMCADASTRO' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &remCadastro1.FromString(&GridStateDynamicFilter.Value) &remCadastro_To1.FromString(&GridStateDynamicFilter.ValueTo) If not &remCadastro1.IsEmpty() OR not &remCadastro_To1.IsEmpty() Do Case Case &DynamicFiltersOperator1 = 0 &FilterremCadastroDescription = format('%1 (%2)', "Mês e Ano", "WWP_FilterRange") &remCadastro = &remCadastro1 print printBlockFilterremCadastro &FilterremCadastroDescription = format('%1 (%2) %3', "Mês e Ano", "WWP_FilterRange", "") &remCadastro = &remCadastro_To1 print printBlockFilterremCadastro EndCase EndIf Case &DynamicFiltersSelector1 = !'REMSTATUS' &remStatus1.FromString(&GridStateDynamicFilter.Value) If not &remStatus1.IsEmpty() &FilterremStatus1ValueDescription = '' Do Case Case &remStatus1.ToString().Trim() = !"A" &FilterremStatus1ValueDescription = "Ativo"
Case &remStatus1.ToString().Trim() = !"I" &FilterremStatus1ValueDescription = "Inativo"
EndCase
&FilterremStatusValueDescription = &FilterremStatus1ValueDescription print printBlockFilterremStatus EndIf EndCase If &GridState.DynamicFilters.Count >= 2 &DynamicFiltersEnabled2 = True &GridStateDynamicFilter = &GridState.DynamicFilters.Item(2) &DynamicFiltersSelector2 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector2 = !'REMCODIGO' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &remCodigo2.FromString(&GridStateDynamicFilter.Value) If not &remCodigo2.IsEmpty() Do Case Case &DynamicFiltersOperator2 = 0 &FilterremCodigoDescription = format('%1 (%2)', "Código", "=") EndCase &remCodigo = &remCodigo2 print printBlockFilterremCodigo EndIf Case &DynamicFiltersSelector2 = !'REMCADASTRO' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &remCadastro2.FromString(&GridStateDynamicFilter.Value) &remCadastro_To2.FromString(&GridStateDynamicFilter.ValueTo) If not &remCadastro2.IsEmpty() OR not &remCadastro_To2.IsEmpty() Do Case Case &DynamicFiltersOperator2 = 0 &FilterremCadastroDescription = format('%1 (%2)', "Mês e Ano", "WWP_FilterRange") &remCadastro = &remCadastro2 print printBlockFilterremCadastro &FilterremCadastroDescription = format('%1 (%2) %3', "Mês e Ano", "WWP_FilterRange", "") &remCadastro = &remCadastro_To2 print printBlockFilterremCadastro EndCase EndIf Case &DynamicFiltersSelector2 = !'REMSTATUS' &remStatus2.FromString(&GridStateDynamicFilter.Value) If not &remStatus2.IsEmpty() &FilterremStatus2ValueDescription = '' Do Case Case &remStatus2.ToString().Trim() = !"A" &FilterremStatus2ValueDescription = "Ativo"
Case &remStatus2.ToString().Trim() = !"I" &FilterremStatus2ValueDescription = "Inativo"
EndCase
&FilterremStatusValueDescription = &FilterremStatus2ValueDescription print printBlockFilterremStatus EndIf EndCase If &GridState.DynamicFilters.Count >= 3 &DynamicFiltersEnabled3 = True &GridStateDynamicFilter = &GridState.DynamicFilters.Item(3) &DynamicFiltersSelector3 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector3 = !'REMCODIGO' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &remCodigo3.FromString(&GridStateDynamicFilter.Value) If not &remCodigo3.IsEmpty() Do Case Case &DynamicFiltersOperator3 = 0 &FilterremCodigoDescription = format('%1 (%2)', "Código", "=") EndCase &remCodigo = &remCodigo3 print printBlockFilterremCodigo EndIf Case &DynamicFiltersSelector3 = !'REMCADASTRO' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &remCadastro3.FromString(&GridStateDynamicFilter.Value) &remCadastro_To3.FromString(&GridStateDynamicFilter.ValueTo) If not &remCadastro3.IsEmpty() OR not &remCadastro_To3.IsEmpty() Do Case Case &DynamicFiltersOperator3 = 0 &FilterremCadastroDescription = format('%1 (%2)', "Mês e Ano", "WWP_FilterRange") &remCadastro = &remCadastro3 print printBlockFilterremCadastro &FilterremCadastroDescription = format('%1 (%2) %3', "Mês e Ano", "WWP_FilterRange", "") &remCadastro = &remCadastro_To3 print printBlockFilterremCadastro EndCase EndIf Case &DynamicFiltersSelector3 = !'REMSTATUS' &remStatus3.FromString(&GridStateDynamicFilter.Value) If not &remStatus3.IsEmpty() &FilterremStatus3ValueDescription = '' Do Case Case &remStatus3.ToString().Trim() = !"A" &FilterremStatus3ValueDescription = "Ativo"
Case &remStatus3.ToString().Trim() = !"I" &FilterremStatus3ValueDescription = "Inativo"
EndCase
&FilterremStatusValueDescription = &FilterremStatus3ValueDescription print printBlockFilterremStatus EndIf EndCase EndIf EndIf EndIf If not (&TFremCodigo.IsEmpty() AND &TFremCodigo_To.IsEmpty()) print printBlockTFremCodigo &TFremCodigo_To_Description = format('%1 (%2)', "Código", "WWP_TSTo") print printBlockTFremCodigo_To EndIf If not (&TFremCadastro.IsEmpty() AND &TFremCadastro_To.IsEmpty()) print printBlockTFremCadastro &TFremCadastro_To_Description = format('%1 (%2)', "Mês e Ano", "WWP_TSTo") print printBlockTFremCadastro_To EndIf If not &TFremPeriodo1_Sel.IsEmpty() print printBlockTFremPeriodo1_Sel Else If not &TFremPeriodo1.IsEmpty() print printBlockTFremPeriodo1 EndIf EndIf If not &TFremPeriodo2_Sel.IsEmpty() print printBlockTFremPeriodo2_Sel Else If not &TFremPeriodo2.IsEmpty() print printBlockTFremPeriodo2 EndIf EndIf If not &TFremPeriodo3_Sel.IsEmpty() print printBlockTFremPeriodo3_Sel Else If not &TFremPeriodo3.IsEmpty() print printBlockTFremPeriodo3 EndIf EndIf If not &TFremPeriodo4_Sel.IsEmpty() print printBlockTFremPeriodo4_Sel Else If not &TFremPeriodo4.IsEmpty() print printBlockTFremPeriodo4 EndIf EndIf If not &TFremPeriodo5_Sel.IsEmpty() print printBlockTFremPeriodo5_Sel Else If not &TFremPeriodo5.IsEmpty() print printBlockTFremPeriodo5 EndIf EndIf &TFremStatus_Sels.FromJson(&TFremStatus_SelsJson) If not &TFremStatus_Sels.Count = 0 &i = 1 For &TFremStatus_Sel in &TFremStatus_Sels If &i = 1 &TFremStatus_SelDscs = '' Else &TFremStatus_SelDscs += ', ' EndIf &FilterTFremStatus_SelValueDescription = '' Do Case Case &TFremStatus_Sel.ToString().Trim() = !"A" &FilterTFremStatus_SelValueDescription = "Ativo"
Case &TFremStatus_Sel.ToString().Trim() = !"I" &FilterTFremStatus_SelValueDescription = "Inativo"
EndCase
&TFremStatus_SelDscs += &FilterTFremStatus_SelValueDescription &i += 1 EndFor print printBlockTFremStatus_Sel EndIf
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'PrintColumnTitles'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
print printBlockBeforeGrid print printBlockLines_titles
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'PrintData'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
For each trnsremessas order remStatus when &OrderedBy = 1 AND &OrderedDsc = False order (remStatus) when &OrderedBy = 1 AND &OrderedDsc = True order remCodigo when &OrderedBy = 2 AND &OrderedDsc = False order (remCodigo) when &OrderedBy = 2 AND &OrderedDsc = True order remCadastro when &OrderedBy = 3 AND &OrderedDsc = False order (remCadastro) when &OrderedBy = 3 AND &OrderedDsc = True
using trnsremessasWWDS(&DynamicFiltersSelector1, &DynamicFiltersOperator1, &remCodigo1, &remCadastro1, &remCadastro_To1, &remStatus1 , &DynamicFiltersEnabled2, &DynamicFiltersSelector2, &DynamicFiltersOperator2, &remCodigo2, &remCadastro2, &remCadastro_To2 , &remStatus2, &DynamicFiltersEnabled3, &DynamicFiltersSelector3, &DynamicFiltersOperator3, &remCodigo3, &remCadastro3 , &remCadastro_To3, &remStatus3, &TFremCodigo, &TFremCodigo_To, &TFremCadastro, &TFremCadastro_To , &TFremPeriodo1, &TFremPeriodo1_Sel, &TFremPeriodo2, &TFremPeriodo2_Sel, &TFremPeriodo3, &TFremPeriodo3_Sel , &TFremPeriodo4, &TFremPeriodo4_Sel, &TFremPeriodo5, &TFremPeriodo5_Sel, &TFremStatus_Sels) Where prefCodigo = &prefCodigo &remStatusDescription = '' Do Case Case remStatus.ToString().Trim() = !"A" &remStatusDescription = "Ativo"
Case remStatus.ToString().Trim() = !"I" &remStatusDescription = "Inativo"
EndCase
Do 'BeforePrintLine' print printBlockLines_data Do 'AfterPrintLine' EndFor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'LoadGridState'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
// Load grid state from session. If &Session.Get(!"trnsremessasWWGridState") = !"" &GridState.FromXml(LoadGridState.Udp(!"trnsremessasWWGridState")) Else &GridState.FromXml(&Session.Get(!"trnsremessasWWGridState")) Endif
&OrderedBy = &GridState.OrderedBy &OrderedDsc = &GridState.OrderedDsc
For &GridStateFilterValue in &GridState.FilterValues Do Case Case &GridStateFilterValue.Name = !"TFREMCODIGO" &TFremCodigo.FromString(&GridStateFilterValue.Value) &TFremCodigo_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFREMCADASTRO" &TFremCadastro.FromString(&GridStateFilterValue.Value) &TFremCadastro_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFREMPERIODO1" &TFremPeriodo1.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFREMPERIODO1_SEL" &TFremPeriodo1_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFREMPERIODO2" &TFremPeriodo2.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFREMPERIODO2_SEL" &TFremPeriodo2_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFREMPERIODO3" &TFremPeriodo3.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFREMPERIODO3_SEL" &TFremPeriodo3_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFREMPERIODO4" &TFremPeriodo4.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFREMPERIODO4_SEL" &TFremPeriodo4_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFREMPERIODO5" &TFremPeriodo5.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFREMPERIODO5_SEL" &TFremPeriodo5_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFREMSTATUS_SEL" &TFremStatus_SelsJson = &GridStateFilterValue.Value &TFremStatus_Sels.FromJson(&TFremStatus_SelsJson) EndCase EndFor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
